import torch
from torch import nn

class Ensemble(nn.Module):
    def __init__(self):
        super().__init__()
        self.members = nn.ModuleList([
            build_registered_model('cnn', {'hidden_dim': 32, 'depth': 2}),
            build_registered_model('gru', {'hidden_dim': 32}),
        ])
        self.weights = nn.Parameter(torch.zeros(2))

    def forward(self, x):
        logits = torch.stack([member(x) for member in self.members], dim=0)
        weights = self.weights.softmax(dim=0).view(-1, 1, 1)
        return (logits * weights).sum(dim=0)

def build_model(input_dim, num_classes, params):
    return Ensemble()
